// Types of the module generated by scripts/build-runtime.mjs (dist/libs-source.js).

/** A vendored library (interactive mode, ADR-020): its pinned files, embedded inline in scripted documents. */
export interface LibSource {
  /** The library's JavaScript, a classic script. */
  js: string;
  /** Its stylesheet, or `""`. */
  css: string;
  /** SHA-256 of `js` in base64: the CSP hash source `'sha256-<this>'`. */
  jsSha256: string;
}

/** Every library of `LIB_CATALOG` (`@pptaken/schema`), by id. The build fails when a file does not match its hash. */
export declare const LIB_SOURCES: Readonly<Record<string, LibSource>>;
